#!/usr/bin/env bash
set -euo pipefail

if sudo -n kubectl version --client >/dev/null 2>&1; then
  KUBECTL=(sudo -n kubectl)
elif sudo -n k3s kubectl version --client >/dev/null 2>&1; then
  KUBECTL=(sudo -n k3s kubectl)
else
  echo "ERROR: no sanctioned non-interactive Kubernetes client is available" >&2
  exit 1
fi

namespace="endless"
release="endless-game-show"
archive_sha="36c82522aa99fbc0872860b77ed83f4903ac3bcf1eaecc101f8382d4bd935444"
configmap="endless-app-36c82522aa99"
tmp_dir="$(mktemp -d)"
trap 'rm -rf "$tmp_dir"' EXIT

cat >"$tmp_dir/app.tar.gz.b64" <<'ARCHIVE_BASE64'

ARCHIVE_BASE64
base64 -d "$tmp_dir/app.tar.gz.b64" >"$tmp_dir/app.tar.gz"
printf '%s  %s\n' "$archive_sha" "$tmp_dir/app.tar.gz" | sha256sum -c -

"${KUBECTL[@]}" create namespace "$namespace" --dry-run=client -o yaml | "${KUBECTL[@]}" apply -f -
"${KUBECTL[@]}" -n "$namespace" create configmap "$configmap" \
  --from-file=app.tar.gz="$tmp_dir/app.tar.gz" \
  --dry-run=client -o yaml | "${KUBECTL[@]}" apply -f -

cat >"$tmp_dir/resources.yaml" <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: $release
  namespace: $namespace
  labels:
    app.kubernetes.io/name: $release
spec:
  replicas: 1
  strategy:
    type: Recreate
  selector:
    matchLabels:
      app.kubernetes.io/name: $release
  template:
    metadata:
      labels:
        app.kubernetes.io/name: $release
      annotations:
        endless.dcgames.uk/archive-sha256: "$archive_sha"
    spec:
      initContainers:
        - name: unpack
          image: busybox:1.36
          command: ["sh", "-c", "tar -xzf /payload/app.tar.gz -C /app"]
          volumeMounts:
            - name: archive
              mountPath: /payload
              readOnly: true
            - name: app
              mountPath: /app
      containers:
        - name: web
          image: node:20-alpine
          command: ["node", "/app/server.js"]
          env:
            - name: PORT
              value: "7777"
          ports:
            - name: http
              containerPort: 7777
          readinessProbe:
            httpGet:
              path: /api/hello
              port: http
            initialDelaySeconds: 2
            periodSeconds: 5
          livenessProbe:
            httpGet:
              path: /api/hello
              port: http
            initialDelaySeconds: 10
            periodSeconds: 15
          resources:
            requests:
              cpu: 25m
              memory: 48Mi
            limits:
              cpu: 500m
              memory: 256Mi
          volumeMounts:
            - name: app
              mountPath: /app
      volumes:
        - name: archive
          configMap:
            name: $configmap
        - name: app
          emptyDir: {}
---
apiVersion: v1
kind: Service
metadata:
  name: $release
  namespace: $namespace
spec:
  selector:
    app.kubernetes.io/name: $release
  ports:
    - name: http
      port: 80
      targetPort: http
---
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata:
  name: $release
  namespace: $namespace
spec:
  ingressClassName: traefik
  rules:
    - host: endless.dcgames.uk
      http:
        paths:
          - path: /
            pathType: Prefix
            backend:
              service:
                name: $release
                port:
                  name: http
EOF

"${KUBECTL[@]}" apply -f "$tmp_dir/resources.yaml"
"${KUBECTL[@]}" -n "$namespace" rollout status "deployment/$release" --timeout=180s
"${KUBECTL[@]}" -n "$namespace" get deployment,pod,service,ingress -o wide
"${KUBECTL[@]}" -n "$namespace" get endpoints "$release" -o wide
curl -fsS --max-time 20 https://endless.dcgames.uk/api/hello
curl -fsS --max-time 20 -o /dev/null -w 'show_http=%{http_code}\n' https://endless.dcgames.uk/show
curl -fsS --max-time 20 -o /dev/null -w 'play_http=%{http_code}\n' https://endless.dcgames.uk/play
